module Counter_4bit_Synch_Clr (output [3: 0]  A, output next_stage, input Count_enable, Clear, CLK);  wire A0, A1, A2, A3;  assign A[3: 0] = {A3, A2, A1, A0};  JK_FF M0 (A0, J0, K0, CLK);  JK_FF M1 (A1, J1, K1, CLK);  JK_FF M2 (A2, J2, K2, CLK);  JK_FF M3 (A3, J3, K3, CLK);  not (Clear_b, Clear);  and (J0, Count_enable, Clear_b);  and (J1, J0, A0);  and (J2, J1, A1);  and (J3, J2, A2);  or (K0, Clear, J0);  or (K1, Clear, J1);  or (K2, Clear, J2);  or (K3, Clear, J3);  and (next_stage, A3, J3);endmodulemodule JK_FF (output reg Q, input J, K, clock);  always @ (posedge clock)    case ({J,K})      2'b00:	Q <= Q;      2'b01:	Q <= 0;      2'b10:	Q <= 1;      2'b11:	Q <= ~Q;    endcaseendmodulemodule t_Counter_4bit_Synch_Clr ();  wire [3: 0]  A;  wire next_stage;   reg Count_enable, Clear, clock;  Counter_4bit_Synch_Clr M0 (A, next_stage, Count_enable, Clear, clock);  initial #300 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    Clear = 1;    Count_enable = 0;     #12 Clear = 0;    #20 Count_enable = 1;    #180 Clear = 1;    #190 Clear = 0;    #230 Count_enable = 0;  joinendmodule